import numpy as np
from scipy.optimize import least_squares

_params = None

def _values(p, rows):
    j0, beta, rho, c = p
    u = np.array([r['u_now'] / 0.02 for r in rows], dtype=float)
    s = np.array([r['s_grad'] for r in rows], dtype=float)
    return j0 * u * np.exp(-beta / (0.5 + u)) * (1.0 - rho * s / (1.0 + s)) + c * np.sqrt(u)

def fit(train_rows):
    global _params
    rows = list(train_rows)
    y = np.array [r['y'] for r in rows]
    y = np.asarray(y, dtype=float)
    best = None
    for beta in (0.2, 1.0, 3.0, 8.0):
        for rho in (0.3, 0.7, 1.0):
            result = least_squares(lambda p: _values(p, rows) - y,
                                   [2.0, beta, rho, 0.2],
                                   bounds=([0.0, 0.0, 0.0, -np.inf],
                                           [np.inf, np.inf, 1.0, np.inf]),
                                   max_nfev=5000)
            if best is None or np.dot(result.fun, result.fun) < np.dot(best.fun, best.fun):
                best = result
    _params = best.x

def predict(row):
    return float(_values(_params, [row])[0])
